import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./AdminPage.css";

function AdminPage() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("dashboard");
  const [slots, setSlots] = useState([]);
  const [bookings, setBookings] = useState([]);

  useEffect(() => {
    // Fetch all slots
    fetch("http://localhost:8081/api/slots")
      .then((res) => res.json())
      .then((data) => setSlots(data))
      .catch((err) => console.error("Error fetching slots:", err));

    // Fetch all bookings
    fetch("http://localhost:8081/api/bookings")
      .then((res) => res.json())
      .then((data) => setBookings(data))
      .catch((err) => console.error("Error fetching bookings:", err));
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/admin-login");
  };

  const renderContent = () => {
    if (activeTab === "dashboard") {
      return (
        <div className="dashboard-content">
          <div className="stat-card">
            <h3>Total Slots</h3>
            <p>{slots.length}</p>
          </div>
          <div className="stat-card">
            <h3>Available Slots</h3>
            <p>{slots.filter((s) => s.isAvailable).length}</p>
          </div>
          <div className="stat-card">
            <h3>Total Bookings</h3>
            <p>{bookings.length}</p>
          </div>
        </div>
      );
    }

    if (activeTab === "bookings") {
      return (
        <div>
          <h2>All Bookings</h2>
          <table>
            <thead>
              <tr>
                <th>Booking ID</th>
                <th>Vehicle</th>
                <th>Start</th>
                <th>End</th>
                <th>Cost</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((b) => {
                // Keep for internal use
                const slotId = b.parkingSlot?.id;
                const slotNumber = b.parkingSlot?.slotNumber;
                return (
                  <tr key={b.bookingId}>
                    <td>{b.bookingId}</td>
                    <td>{b.vehicleNumber}</td>
                    <td>{new Date(b.startTime).toLocaleString()}</td>
                    <td>{new Date(b.endTime).toLocaleString()}</td>
                    <td>
                      {b.totalCost !== undefined ? `$${b.totalCost}` : "N/A"}
                    </td>
                    <td>{b.status}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      );
    }

    if (activeTab === "slots") {
      return (
        <div>
          <h2>Manage Slots</h2>
          <table>
            <thead>
              <tr>
                <th>ID</th>
                <th>Number</th>
                <th>Type</th>
                <th>Rate</th>
                <th>Available</th>
              </tr>
            </thead>
            <tbody>
              {slots.map((s) => (
                <tr key={s.id}>
                  <td>{s.id}</td>
                  <td>{s.slotNumber}</td>
                  <td>{s.slotType}</td>
                  <td>${s.hourlyRate}</td>
                  <td>{s.isAvailable ? "Yes" : "No"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }
  };

  return (
    <div className="admin-dashboard">
      {/* Sidebar */}
      <div className="sidebar">
        <h2>Admin Panel</h2>
        <ul>
          <li onClick={() => setActiveTab("dashboard")}>Dashboard</li>
          <li onClick={() => setActiveTab("bookings")}>View Bookings</li>
          <li onClick={() => setActiveTab("slots")}>Manage Slots</li>
        </ul>
      </div>

      {/* Main content */}
      <div className="main-content">
        <div className="topbar">
          <h1>{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}</h1>
          <button onClick={handleLogout}>Logout</button>
        </div>
        <div className="content-area">{renderContent()}</div>
      </div>
    </div>
  );
}

export default AdminPage;
